       background:radial-gradient(120% 90% at 50% 58%,rgba(0,0,0,0) 32%,rgba(4,3,6,.55) 72%,rgba(3,2,5,.95) 100%);}
  #grain{position:fixed;inset:-50%;pointer-events:none;opacity:.045;mix-blend-mode:overlay;}
</style>
</head>
<body>
<canvas id="c"></canvas>
<canvas id="grain"></canvas>
<div id="vig"></div>
<script>
(function(){
"use strict";

var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
try{ window.matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',function(e){reduce=e.matches;}); }catch(e){}

var cv = document.getElementById('c'), ctx = cv.getContext('2d');
var W=0,H=0,DPR=1,S=1,CX=0,CY=0;

/* ---------- steam offscreen ---------- */
var sc = document.createElement('canvas'), sx = sc.getContext('2d');

function resize(){
  DPR = Math.min(window.devicePixelRatio||1, 2);
  W = window.innerWidth; H = window.innerHeight;
  cv.width = Math.round(W*DPR); cv.height = Math.round(H*DPR);
  ctx.setTransform(DPR,0,0,DPR,0,0);
  // design space is 1000x1000; fit the bowl generously on any aspect
  S = Math.min(W/900, H/980);
  S = Math.max(S, Math.min(W/760, H/1180)*1.0);
  CX = W*0.5; CY = H*0.54;
  sc.width = Math.max(1,Math.round(W*0.5)); sc.height = Math.max(1,Math.round(H*0.5));
  buildGrain();
}
window.addEventListener('resize', resize);

/* ---------- grain ---------- */
var gcv = document.getElementById('grain'), gx = gcv.getContext('2d');
function buildGrain(){
  var w=180,h=180; gcv.width=w; gcv.height=h;
  gcv.style.width='200%'; gcv.style.height='200%';
  var img=gx.createImageData(w,h), d=img.data;
  for(var i=0;i<d.length;i+=4){ var v=(Math.random()*255)|0; d[i]=d[i+1]=d[i+2]=v; d[i+3]=255; }
  gx.putImageData(img,0,0);
}

/* ---------- input ---------- */
var mx=0.5,my=0.5, tmx=0.5,tmy=0.5, active=0, tactive=0;
function pointer(x,y){ tmx = x/W; tmy = y/H; tactive=1; }
window.addEventListener('mousemove',function(e){pointer(e.clientX,e.clientY);},{passive:true});
window.addEventListener('mouseleave',function(){tactive=0;tmx=0.5;tmy=0.5;});
window.addEventListener('touchmove',function(e){var t=e.touches[0]; if(t) pointer(t.clientX,t.clientY);},{passive:true});
window.addEventListener('touchend',function(){tactive=0;tmx=0.5;tmy=0.5;});

/* ---------- noise ---------- */
var P=new Uint8Array(512);
(function(){var p=[];for(var i=0;i<256;i++)p[i]=i;
 for(var i=255;i>0;i--){var j=(Math.random()*(i+1))|0,t=p[i];p[i]=p[j];p[j]=t;}
 for(var i=0;i<512;i++)P[i]=p[i&255];})();
function fade(t){return t*t*t*(t*(t*6-15)+10);}
function lerp(a,b,t){return a+(b-a)*t;}
function grad(h,x,y){var u=(h&1)?x:y,v=(h&2)?y:x;return ((h&4)?-u:u)+((h&8)?-v:v);}
function noise2(x,y){
  var X=Math.floor(x)&255, Y=Math.floor(y)&255;
  x-=Math.floor(x); y-=Math.floor(y);
  var u=fade(x),v=fade(y);
  var A=P[X]+Y, B=P[X+1]+Y;
  return lerp(lerp(grad(P[A],x,y),grad(P[B],x-1,y),u),
              lerp(grad(P[A+1],x,y-1),grad(P[B+1],x-1,y-1),u),v);
}

/* ---------- steam particles ---------- */
var puffs=[];
function spawnPuff(t){
  var a=(Math.random()*2-1);
  puffs.push({
    x:a*150*Math.sqrt(Math.random()),
    y:-30+Math.random()*20,
    vy:-(22+Math.random()*16),
    vx:a*4,
    r:34+Math.random()*40,
    life:0, max:5.2+Math.random()*3.4,
    seed:Math.random()*100,
    sw:0.55+Math.random()*0.6
  });
}
for(var i=0;i<30;i++){ spawnPuff(0); var p=puffs[puffs.length-1]; p.life=Math.random()*p.max; }

/* ---------- helpers ---------- */
function rgba(r,g,b,a){return 'rgba('+r+','+g+','+b+','+a+')';}

function ellipsePath(g,x,y,rx,ry){ g.beginPath(); g.ellipse(x,y,rx,ry,0,0,Math.PI*2); }

/* ---------- scene drawing (design units, origin = bowl center) ---------- */
var RIMX=300, RIMY=96, RIMCY=0;          // rim ellipse
var BROTHY=RIMCY+16, BRX=272, BRY=84;    // broth surface

function drawBackdrop(t,lx,ly){
  // deep vertical wash
  var g=ctx.createLinearGradient(0,0,0,H);
  g.addColorStop(0,'#0a0810'); g.addColorStop(0.55,'#0b0a10'); g.addColorStop(1,'#050408');
  ctx.fillStyle=g; ctx.fillRect(0,0,W,H);

  // warm ambient bloom rising from the bowl
  var bx=CX+lx*26, by=CY-40*S+ly*18;
  var r=Math.max(W,H)*0.75;
  var rg=ctx.createRadialGradient(bx,by,0,bx,by,r);
  rg.addColorStop(0,'rgba(255,168,84,0.20)');
  rg.addColorStop(0.22,'rgba(226,120,52,0.10)');
  rg.addColorStop(0.5,'rgba(120,60,40,0.04)');
  rg.addColorStop(1,'rgba(0,0,0,0)');
  ctx.globalCompositeOperation='lighter';
  ctx.fillStyle=rg; ctx.fillRect(0,0,W,H);

  // cool rim light from upper opposite side
  var cx2=CX-lx*W*0.42, cy2=CY-H*0.42;
  var cg=ctx.createRadialGradient(cx2,cy2,0,cx2,cy2,Math.max(W,H)*0.7);
  cg.addColorStop(0,'rgba(90,120,180,0.10)');
  cg.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle=cg; ctx.fillRect(0,0,W,H);
  ctx.globalCompositeOperation='source-over';

  // table plane
  var ty=CY+RIMY*1.05*S+150*S;
  var tg=ctx.createLinearGradient(0,ty-260*S,0,H);
  tg.addColorStop(0,'rgba(0,0,0,0)');
  tg.addColorStop(0.5,'rgba(26,17,14,0.55)');
  tg.addColorStop(1,'rgba(10,7,7,0.9)');
  ctx.fillStyle=tg; ctx.fillRect(0,ty-260*S,W,H-(ty-260*S));
}

function drawShadow(){
  ctx.save();
  ctx.translate(CX,CY); ctx.scale(S,S);
  ctx.globalCompositeOperation='multiply';
  var y=250;
  var g=ctx.createRadialGradient(0,y,0,0,y,430);
  g.addColorStop(0,'rgba(0,0,0,0.85)');
  g.addColorStop(0.45,'rgba(0,0,0,0.45)');
  g.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle=g;
  ctx.save(); ctx.translate(0,y); ctx.scale(1,0.26); ctx.translate(0,-y);
  ctx.beginPath(); ctx.arc(0,y,430,0,Math.PI*2); ctx.fill(); ctx.restore();
  ctx.restore();
}

function bowlBodyPath(g){
  g.beginPath();
  g.moveTo(-RIMX,RIMCY);
  g.bezierCurveTo(-RIMX+4,RIMCY+120, -196,232, -104,244);
  g.bezierCurveTo(-40,252, 40,252, 104,244);
  g.bezierCurveTo(196,232, RIMX-4,RIMCY+120, RIMX,RIMCY);
  g.bezierCurveTo(RIMX,RIMCY+RIMY*0.62, RIMX*0.62,RIMCY+RIMY, 0,RIMCY+RIMY);
  g.bezierCurveTo(-RIMX*0.62,RIMCY+RIMY, -RIMX,RIMCY+RIMY*0.62, -RIMX,RIMCY);
  g.closePath();
}

function drawBowl(t,lx){
  ctx.save(); ctx.translate(CX,CY); ctx.scale(S,S);

  // outer body
  bowlBodyPath(ctx);
  var g=ctx.createLinearGradient(-RIMX,0,RIMX,180);
  g.addColorStop(0,'#231d22');
  g.addColorStop(0.34,'#171318');
  g.addColorStop(0.62,'#0f0c11');
  g.addColorStop(1,'#1c161a');
  ctx.fillStyle=g; ctx.fill();

  // glaze sheen following the light
  ctx.save(); bowlBodyPath(ctx); ctx.clip();
  var sxp=-lx*180;
  var sg=ctx.createRadialGradient(sxp,60,10,sxp,60,330);
  sg.addColorStop(0,'rgba(255,186,120,0.15)');
  sg.addColorStop(0.5,'rgba(200,130,90,0.05)');
  sg.addColorStop(1,'rgba(0,0,0,0)');
  ctx.globalCompositeOperation='lighter'; ctx.fillStyle=sg;
  ctx.fillRect(-RIMX,-RIMY,RIMX*2,340);

  // warm bounce from the broth onto the inner-lower wall
  var bg=ctx.createLinearGradient(0,RIMCY,0,RIMCY+200);
  bg.addColorStop(0,'rgba(255,140,60,0.20)');
  bg.addColorStop(1,'rgba(255,110,40,0)');
  ctx.fillStyle=bg; ctx.fillRect(-RIMX,RIMCY,RIMX*2,220);
  ctx.globalCompositeOperation='source-over';

  // dark foot / contact shading
  var fg=ctx.createLinearGradient(0,150,0,252);
  fg.addColorStop(0,'rgba(0,0,0,0)'); fg.addColorStop(1,'rgba(0,0,0,0.75)');
  ctx.fillStyle=fg; ctx.fillRect(-RIMX,150,RIMX*2,110);
  ctx.restore();

  // rim: outer ellipse then inner well
  ellipsePath(ctx,0,RIMCY,RIMX,RIMY);
  var rg=ctx.createLinearGradient(-RIMX,-RIMY,RIMX,RIMY);
  rg.addColorStop(0,'#3a2f34'); rg.addColorStop(0.5,'#221c20'); rg.addColorStop(1,'#332a2e');
  ctx.fillStyle=rg; ctx.fill();

  // rim highlight stroke
  ctx.save(); ctx.lineWidth=2.2;
  var hg=ctx.createLinearGradient(-RIMX,0,RIMX,0);
  hg.addColorStop(0,'rgba(255,205,150,0.10)');
  hg.addColorStop(0.5-lx*0.35,'rgba(255,222,180,0.55)');
  hg.addColorStop(1,'rgba(255,205,150,0.10)');
  ctx.strokeStyle=hg; ellipsePath(ctx,0,RIMCY,RIMX,RIMY); ctx.stroke();
  ctx.restore();

  // inner wall
  ellipsePath(ctx,0,RIMCY+6,RIMX-24,RIMY-18);
  var ig=ctx.createLinearGradient(0,RIMCY-RIMY,0,RIMCY+RIMY);
  ig.addColorStop(0,'#0a0709'); ig.addColorStop(1,'#241a16');
  ctx.fillStyle=ig; ctx.fill();

  ctx.restore();
}

/* broth + contents live inside the broth ellipse clip */
function drawBroth(t,lx,ly){
  ctx.save(); ctx.translate(CX,CY); ctx.scale(S,S);
  ctx.save();
  ellipsePath(ctx,0,BROTHY,BRX,BRY); ctx.clip();

  // base broth
  var g=ctx.createLinearGradient(0,BROTHY-BRY,0,BROTHY+BRY);
  g.addColorStop(0,'#personally');
  ctx.restore();
  ctx.restore();
}
